from __future__ import annotations

import os
import re

# TODO: Replace once Testpath class has been refactored
from robot.libraries.BuiltIn import RobotNotRunningError

from ..exception import IphyConfigValidationError
from ..filecollector.testpath import Testpath
from ..ssh import SshConnectionAdapter


class IphyConfigValidator:

    VALIDATOR_DIR = "/opt/iphy/latest/validator/"
    VALIDATOR_NAME = "iphycfgvalidator_obsai.py"
    EXIT_CODE_MSG = {
        1: "iphy.xml has missing, duplicate or invalid parameters or SCFC file contains no radio module entries",
        2: "one or more of the following are not valid XML files or are not found: iphy.xml, scfc.xml or iphy_db.xml",
        3: "iphy.xml has RMOD/antenna/AxC that is not present in SCFC",
        4: "iphy.xml has NOK matches with SCFC file",
    }

    def __init__(self, ssh_client: SshConnectionAdapter):
        self._client = ssh_client

    def validate(
        self, scfc: str, iphyxml: str, iphydb: str | None = None, **kwargs
    ) -> None:
        """Validates iphy configuration consistency.

        :param string scfc:            Path to SCFC file
        :param string iphyxml:         Path to Iphy configuration file
        :param string iphydb:          Path to Iphy DB (iphy_db) file
        |

        :Supported parameters are available via kwargs:
            * **debug**     (boolean) -  enable debug mode
        """
        debug = "--debug" if kwargs.get("debug") else ""
        iphydb = (
            self._get_abspath(iphydb)
            if iphydb
            else os.path.join(IphyConfigValidator.VALIDATOR_DIR, "iphy_db.xml")
        )
        python_path = os.path.join(
            IphyConfigValidator.VALIDATOR_DIR, IphyConfigValidator.VALIDATOR_NAME
        )
        scf_path = self._get_abspath(scfc)
        iphyxml_path = self._get_abspath(iphyxml)
        ssh_command = (
            f"python {python_path} -s {scf_path} -i {iphyxml_path} -d {iphydb} {debug}"
        )
        stdout, stderr, rc = self._client.execute_command(ssh_command)
        self._save_result(self._remove_formatting(stdout))
        self._validate_rc(rc)

    def _get_abspath(self, filename: str) -> str:
        if self._client.config.host == "127.0.0.1":
            return os.path.abspath(filename)
        else:
            return filename

    def _save_result(self, output: str) -> None:
        result_dir = self._get_result_path()
        if not os.path.exists(result_dir):
            os.makedirs(result_dir)
        with open(os.path.join(result_dir, "iphyvalidator_result.txt"), "w") as f:
            f.write(output)

    def _validate_rc(self, rc: int) -> None:
        if rc != 0:
            raise IphyConfigValidationError(IphyConfigValidator.EXIT_CODE_MSG.get(rc))

    def _get_result_path(self) -> str:
        try:
            return Testpath().get_test_path()
        except RobotNotRunningError:
            return os.getcwd()

    def _remove_formatting(self, output: str) -> str:
        color_pattern = r"\033[[0-9(;(1-9+))*]+m"
        return re.sub(color_pattern, "", output)
